name: Social Copy Generator
on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  social-copy-generator:
    runs-on: ubuntu-latest
    steps:
      - name: Check for existing comment
        id: check_comment
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            const existingComment = comments.find(comment => 
              comment.body.includes('Generate social media copies')
            );

            if (existingComment) {
              console.log('Existing comment found');
              return { commentId: existingComment.id };
            } else {
              console.log('No existing comment found');
              return { commentId: null };
            }

      - name: Post initial comment
        if: steps.check_comment.outputs.commentId == 'null'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const commentBody = `
### Generate Social Media Copies

Check the box below to generate Twitter/X, LinkedIn, and Blog Post content for this PR:

- [ ] Generate social media copies

> This will analyze the PR diff and create engaging social media content using Claude Code.
`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: commentBody
            });

      - name: Monitor for checkbox changes
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            // This step will be triggered by the workflow dispatch or webhook
            // The actual monitoring happens via the workflow trigger on issue_comment
            console.log('Monitoring for checkbox changes...');

      - name: Process checkbox change
        if: github.event_name == 'issue_comment' && contains(github.event.comment.body, 'Generate social media copies')
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const commentBody = github.event.comment.body;
            const isGenerated = commentBody.includes('Generating...') || commentBody.includes('Regenerate');

            if (!isGenerated && commentBody.includes('[x] Generate social media copies')) {
              // Update comment to "Generating..."
              const updatedComment = commentBody.replace(
                '[ ] Generate social media copies',
                '[x] Generating...'
              );

              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: github.event.comment.id,
                body: updatedComment
              });

              // Trigger Claude Code analysis
              // Note: This would require a separate workflow or action that handles Claude Code integration
              console.log('Triggering Claude Code analysis...');
            }
